#if defined(MTP_SEMIHOST_ARGS) && MTP_SEMIHOST_ARGS == 1
// Cortex-M: the kernel's startup () calls os_startup_initialize_args() and
// passes argc/argv to main(), which passes them to os_main(). The kernel's
// own implementation is weak and returns an empty argv unless its semihosting
// system-call group is linked; this strong one reads the command line from
// the debugger (OpenOCD "arm semihosting_cmdline ...") or the emulator, and
// keeps the whole support independent of the port's syscall layer.
extern "C" void
os_startup_initialize_args (int* p_argc, char*** p_argv)
{
  int argc;
  char** argv;
  mtp_semihosting::args (argc, argv);
  *p_argc = argc;
  *p_argv = argv;
}
#endif // MTP_SEMIHOST_ARGS == 1

#if MTP_CONSOLE == 2
// The port's _write () is a weak stub that discards the text; this one is
// the console for stdout and stderr.
extern "C" int
_write (int, const char* data, int size)
{
  if (size > 0)
    {
      mtp_board::emit_for_write (data, static_cast<std::size_t> (size));
    }
  return size;
}
#endif

#if MTP_CONSOLE == 1
// newlib's stdio needs these system calls. The AArch64 port has them
// (src/handlers.cpp); the AArch32 port has none, and µTest++ then does not
// link. Weak, so a port that has them keeps its own. stdout and stderr are
// replaced by start (), so only a write that bypasses them lands here: it
// goes to the same console.
#include <sys/stat.h>

extern "C"
{
  __attribute__ ((weak)) int
  _write (int fd, const char* data, int size)
  {
    if (fd != 1 && fd != 2)
      {
        errno = EBADF;
        return -1;
      }
    if (size > 0)
      {
        mtp_board::emit_for_write (data, static_cast<std::size_t> (size));
      }
    return size;
  }

  __attribute__ ((weak)) int
  _read (int, char*, int)
  {
    errno = ENOSYS;
    return -1;
  }

  __attribute__ ((weak)) int
  _close (int)
  {
    errno = ENOSYS;
    return -1;
  }

  __attribute__ ((weak)) int
  _fstat (int fd, struct stat* st)
  {
    if (fd < 0 || fd > 2 || st == nullptr)
      {
        errno = EBADF;
        return -1;
      }
    std::memset (st, 0, sizeof (*st));
    st->st_mode = S_IFCHR; // a console: line buffered
    return 0;
  }

  __attribute__ ((weak)) int
  _isatty (int fd)
  {
    return fd >= 0 && fd <= 2 ? 1 : 0;
  }

  __attribute__ ((weak)) int
  _lseek (int, int, int)
  {
    errno = ESPIPE;
    return -1;
  }
}
#endif

// ---------------------------------------------------------------------------
// The report file (runner_options::output_file_path).
//
// µTest++ writes its complete report to a file when --output-file is given.
// Its reporter opens that file with fopen(), which needs newlib's _open() and
// the other system calls a bare-metal port usually does not provide. Instead
// of adding a system-call layer to every port, this support wraps fopen (the
// µTest++ CMake block links -Wl,--wrap=fopen) and builds a cookie stream over
// the semihosting file calls. Every file the test opens then goes to the
// debugger/emulator, which is the only filesystem these images have.
#if MTP_CONSOLE != 3
#include <sys/types.h>

namespace
{
  struct report_stream
  {
    int handle;
  };

  constexpr int report_streams = 4;
  report_stream g_report[report_streams];
  bool g_report_used[report_streams] = {};

  ssize_t
  report_write (void* cookie, const char* data, std::size_t size)
  {
    if (size == 0)
      {
        return 0;
      }
    return mtp_semihosting::write (
        static_cast<report_stream*> (cookie)->handle, data, size);
  }

  int
  report_close (void* cookie)
  {
    auto* stream = static_cast<report_stream*> (cookie);
    (void)mtp_semihosting::close (stream->handle);
    const auto slot = static_cast<std::size_t> (stream - g_report);
    if (slot < report_streams)
      {
        g_report_used[slot] = false;
      }
    stream->handle = -1;
    return 0;
  }
} // namespace

extern "C" FILE*
__wrap_fopen (const char* path, const char* mode)
{
  const int handle = mtp_semihosting::open (path, mode);
  if (handle < 0)
    {
      return nullptr;
    }
  for (int i = 0; i < report_streams; ++i)
    {
      if (g_report_used[i])
        {
          continue;
        }
      g_report_used[i] = true;
      g_report[i].handle = handle;
      cookie_io_functions_t functions{};
      functions.write = report_write;
      functions.close = report_close;
      FILE* stream = fopencookie (&g_report[i], mode, functions);
      if (stream != nullptr)
        {
          setvbuf (stream, nullptr, _IOLBF, 0);
          return stream;
        }
      g_report_used[i] = false;
      break;
    }
  (void)mtp_semihosting::close (handle);
  return nullptr;
}
#endif // MTP_CONSOLE != 3

#if defined(MTP_NANO_PRINTF) && MTP_NANO_PRINTF
// newlib-nano's printf has no C99 length modifiers: "%zu" prints "zu" and
// eats no argument, so every count in µTest++'s report comes out wrong
// ("ok zu - ..."). µTest++ hard-codes "%zu" for size_t (detail.h). On this
// target size_t is unsigned int, so dropping the 'z' gives the same
// conversion. The µTest++ block links the printf family through these
// wrappers (-Wl,--wrap=...) and keeps nano's float support (-u _printf_float)
// for "%g" and "%Lg" in the approx () messages.
#include <cstdarg>

static_assert (sizeof (std::size_t) == sizeof (unsigned int),
               "dropping 'z' is only right where size_t is unsigned int");

namespace
{
  // Copy fmt into buf without the 'z' of each conversion; nullptr if fmt
  // has none (the common case). If fmt overflows buf after rewriting a '%z'
  // conversion, buf is cleanly truncated at a conversion boundary so
  // newlib-nano never sees an unconsumed '%zu' argument in va_list.
  const char*
  without_z (const char* fmt, char* buf, std::size_t size) noexcept
  {
    if (fmt == nullptr || size == 0 || std::strchr (fmt, 'z') == nullptr)
      {
        return nullptr;
      }
    std::size_t o = 0;
    bool changed = false;
    for (const char* p = fmt; *p != '\0'; ++p)
      {
        if (*p != '%')
          {
            if (o + 1 >= size)
              {
                buf[o] = '\0';
                return changed ? buf : nullptr;
              }
            buf[o++] = *p;
            continue;
          }
        if (p[1] == '%')
          {
            if (o + 2 >= size)
              {
                buf[o] = '\0';
                return changed ? buf : nullptr;
              }
            buf[o++] = '%';
            buf[o++] = '%'; // "%%" is a literal '%', not a conversion
            ++p;
            continue;
          }
        // Flags, width, precision, then the length modifier.
        const std::size_t spec_start = o;
        if (o + 1 >= size)
          {
            buf[o] = '\0';
            return changed ? buf : nullptr;
          }
        buf[o++] = *p++;
        while (*p != '\0' && std::strchr ("-+ #0123456789.*", *p) != nullptr)
          {
            if (o + 1 >= size)
              {
                buf[spec_start] = '\0';
                return changed ? buf : nullptr;
              }
            buf[o++] = *p++;
          }
        if (*p == 'z')
          {
            changed = true;
            ++p;
          }
        if (*p == '\0')
          {
            buf[spec_start] = '\0';
            break;
          }
        if (o + 1 >= size)
          {
            buf[spec_start] = '\0';
            return changed ? buf : nullptr;
          }
        buf[o++] = *p;
      }
    buf[o] = '\0';
    return changed ? buf : nullptr;
  }

  constexpr std::size_t fmt_size = 128;
} // namespace

#define MTP_FIX_FMT(fmt)                                                      \
  char mtp_fmt_buf_[fmt_size];                                                \
  const char* mtp_fmt_ = without_z ((fmt), mtp_fmt_buf_, fmt_size);           \
  if (mtp_fmt_ == nullptr)                                                    \
    {                                                                         \
      mtp_fmt_ = (fmt);                                                       \
    }

extern "C"
{
  int __real_vprintf (const char*, va_list);
  int __real_vfprintf (FILE*, const char*, va_list);
  int __real_vsnprintf (char*, std::size_t, const char*, va_list);

  int
  __wrap_vprintf (const char* fmt, va_list ap)
  {
    MTP_FIX_FMT (fmt);
    return __real_vprintf (mtp_fmt_, ap);
  }

  int
  __wrap_vfprintf (FILE* f, const char* fmt, va_list ap)
  {
    MTP_FIX_FMT (fmt);
    return __real_vfprintf (f, mtp_fmt_, ap);
  }

  int
  __wrap_vsnprintf (char* s, std::size_t n, const char* fmt, va_list ap)
  {
    MTP_FIX_FMT (fmt);
    return __real_vsnprintf (s, n, mtp_fmt_, ap);
  }

  int
  __wrap_printf (const char* fmt, ...)
  {
    MTP_FIX_FMT (fmt);
    va_list ap;
    va_start (ap, fmt);
    const int r = __real_vprintf (mtp_fmt_, ap);
    va_end (ap);
    return r;
  }

  int
  __wrap_fprintf (FILE* f, const char* fmt, ...)
  {
    MTP_FIX_FMT (fmt);
    va_list ap;
    va_start (ap, fmt);
    const int r = __real_vfprintf (f, mtp_fmt_, ap);
    va_end (ap);
    return r;
  }

  int
  __wrap_snprintf (char* s, std::size_t n, const char* fmt, ...)
  {
    MTP_FIX_FMT (fmt);
    va_list ap;
    va_start (ap, fmt);
    const int r = __real_vsnprintf (s, n, mtp_fmt_, ap);
    va_end (ap);
    return r;
  }
}
#undef MTP_FIX_FMT
#endif
